function addExtraEvents(): int {
    $events=extraEventDefinitions();
    $added=0;
    db()->beginTransaction();
    try {
        foreach ($events as [$title,$club,$category,$creator,$days,$hour,$location,$format,$capacity,$description]) {
            if (one('SELECT id FROM events WHERE title=? AND club_id=? AND created_by=?',[$title,$club,$creator])) continue;
            $start=(new DateTimeImmutable('today',new DateTimeZone('Europe/Minsk')))->modify("+$days days")->setTime($hour,0)->setTimezone(new DateTimeZone('UTC'));
            query("INSERT INTO events (club_id,category_id,created_by,title,description,starts_at,ends_at,location,format,capacity,cover_url,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,'published')",[
                $club,$category,$creator,$title,$description,$start->format('Y-m-d H:i:s'),$start->modify('+2 hours')->format('Y-m-d H:i:s'),$location,$format,$capacity,'/uploads/cover-'.$club.'.svg',
            ]);
            $id=(int)db()->lastInsertId();
            foreach ([7,8,9,10] as $index=>$userId) {
                query('INSERT INTO registrations (user_id,event_id) VALUES (?,?)',[$userId,$id]);
                query('INSERT INTO reactions (user_id,event_id,type) VALUES (?,?,?)',[$userId,$id,$index%2===0?'like':'interested']);
            }
            $added++;
        }
        db()->commit();
    } catch (Throwable $error) {db()->rollBack();throw $error;}
    return $added;
}
if (realpath($_SERVER['SCRIPT_FILENAME'] ?? '')===__FILE__) echo 'Добавлено мероприятий: '.addExtraEvents().PHP_EOL;
